CREATE TABLE cap19_customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, phone TEXT UNIQUE);
CREATE TABLE cap19_orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES cap19_customers(customer_id), order_date TEXT NOT NULL, order_status TEXT NOT NULL);
CREATE TABLE cap19_order_items (order_item_id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES cap19_orders(order_id), product_id INTEGER NOT NULL REFERENCES cap19_products(product_id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price REAL NOT NULL CHECK (unit_price >= 0));

